// odjsonParseFrom decodes the next value in dec into v,
// driving the decoder token by token so the document is
// parsed once rather than twice.
func (v *Named) odjsonParseFrom(dec *jsontext.Decoder, sc *odjsonrt.StringCache) error {
	var err error
	_ = err
	if odjsonrt.WholeValue(dec) {
		var val jsontext.Value
		if val, err = dec.ReadValue(); err != nil {
			return err
		}
		_, err = v.odjsonParseV2(val, 0, sc, false)
		return err
	}
	switch odjsonrt.NextKind(dec) {
	case 'n':
		if _, err = dec.ReadToken(); err != nil {
			return err
		}
		*v = Named{}
		return nil
	case '{':
	default:
		return odjsonrt.ErrKindFrom(dec, "Named")
	}
	if _, err = dec.ReadToken(); err != nil {
		return err
	}
	for odjsonrt.NextKind(dec) != '}' {
		var key jsontext.Value
		key, err = dec.ReadValue()
		if err != nil {
			return err
		}
		idx := -1
		switch string(key) {
		case "\"value\"":
			idx = 0
		}
		if idx < 0 && bytes.IndexByte(key, '\\') >= 0 {
			if name, ok := odjsonrt.UnquoteName(key); ok {
				switch string(name) {
				case "value":
					idx = 0
				}
			}
		}
		switch idx {
		case 0:
			var val121 jsontext.Value
			val121, err = dec.ReadValue()
			if err != nil {
				return err
			}
			if val121[0] == 'n' {
				v.Value = 0
			} else {
				var x122 int64
				x122, _, err = odjsonrt.ParseInt(val121, 0, 64)
				if err != nil {
					return err
				}
				v.Value = int(x122)
			}
		default:
			if _, err = dec.ReadValue(); err != nil {
				return err
			}
		}
	}
	_, err = dec.ReadToken()
	return err
}

// odjsonSizeNamed sizes the buffer the encoders allocate.
var odjsonSizeNamed odjsonrt.SizeHint

// MarshalJSON implements encoding/json.Marshaler.
func (v Named) MarshalJSON() ([]byte, error) {
	buf, err := v.odjsonAppend(odjsonSizeNamed.New(), odjsonrt.ModeHTML)
	if err != nil {
		return nil, err
	}
	odjsonSizeNamed.Record(buf)
	return buf, nil
}

// UnmarshalJSON implements encoding/json.Unmarshaler.
func (v *Named) UnmarshalJSON(data []byte) error {
	// The cache plays the part of encoding/json/v2's string cache: a
	// value that recurs in the document is allocated once.
	sc := odjsonrt.GetStringCache()
	p, err := v.odjsonParse(data, odjsonrt.SkipSpace(data, 0), sc)
	odjsonrt.PutStringCache(sc)
	if err != nil {
		return err
	}
	return odjsonrt.EndOfDocument(data, p)
}

// MarshalJSONTo implements encoding/json/v2.MarshalerTo.
func (v Named) MarshalJSONTo(enc *jsontext.Encoder) error {
	// Under a plain json.Marshal, from encoding/json/v2 or encoding/json,
	// the value is appended straight into the encoder's buffer at any
	// depth; see odjsonrt.BeginDirectEncodeMode for what qualifies and
	// for the mode, which does that call's escaping itself since nothing
	// downstream looks at the bytes.
	if buf, m, ok := odjsonrt.BeginDirectEncodeMode(enc); ok {
		n := len(buf)
		buf, err := v.odjsonAppend(buf, m)
		if err != nil {
			return err
		}
		odjsonSizeNamed.Record(buf[n:])
		odjsonrt.EndDirectEncode(enc, buf)
		return nil
	}
	// Otherwise WriteValue copies what it is given, so the scratch buffer
	// can go straight back to the pool. ModeStream leaves the HTML escaping
	// and the UTF-8 validation to the encoder, which performs both while
	// reformatting the value either way.
	buf := odjsonrt.GetBuffer()
	var err error
	if buf.B, err = v.odjsonAppend(buf.B, odjsonrt.ModeStream); err == nil {
		odjsonSizeNamed.Record(buf.B)
		err = enc.WriteValue(buf.B)
	}
	odjsonrt.PutBuffer(buf)
	return err
}

// UnmarshalJSONFrom implements encoding/json/v2.UnmarshalerFrom.
func (v *Named) UnmarshalJSONFrom(dec *jsontext.Decoder) error {
	// The cache plays the part of json/v2's own string cache: a value
	// that recurs in the document is allocated once.
	sc := odjsonrt.GetStringCache()
	var err error
	// Under a plain json.Unmarshal the value is parsed straight out of
	// the decoder's buffer at any depth; see odjsonrt.BeginDirectDecodeAt
	// for what qualifies. Nobody has validated those bytes, so
	// odjsonParseV2 rejects what jsontext would have.
	if data, p, ok := odjsonrt.BeginDirectDecodeAt(dec); ok {
		var end int
		if end, err = v.odjsonParseV2(data, p, sc, true); err == nil {
			odjsonrt.EndDirectDecodeAt(dec, p, end)
		}
	} else {
		err = v.odjsonParseFrom(dec, sc)
	}
	odjsonrt.PutStringCache(sc)
	return err
}

// odjsonAppend appends the JSON encoding of v to dst.
func (v *Promoted) odjsonAppend(dst []byte, m odjsonrt.StringMode) ([]byte, error) {
	var err error
	_ = err
	start := len(dst)
	dst = append(dst, ",\"deep_only\":\""...)
	dst, err = odjsonrt.AppendStringBodyChecked(dst, string(v.Mid.Deep.DeepOnly), m)
	if err != nil {
		return nil, err
	}
	dst = append(dst, "\",\"shared\":\""...)
	dst, err = odjsonrt.AppendStringBodyChecked(dst, string(v.Mid.Shared), m)
	if err != nil {
		return nil, err
	}
	dst = append(dst, "\",\"mid_only\":"...)
	dst = odjsonrt.AppendInt(dst, int64(v.Mid.MidOnly))
	dst = append(dst, ",\"left\":\""...)
	dst, err = odjsonrt.AppendStringBodyChecked(dst, string(v.LeftConflict.Left), m)
	if err != nil {
		return nil, err
	}
	dst = append(dst, "\",\"right\":\""...)
	dst, err = odjsonrt.AppendStringBodyChecked(dst, string(v.RightConflict.Right), m)
	if err != nil {
		return nil, err
	}
	dst = append(dst, "\",\"Winner\":\""...)
	dst, err = odjsonrt.AppendStringBodyChecked(dst, string(v.TaggedSide.Winner), m)
	if err != nil {
		return nil, err
	}
	dst = append(dst, "\""...)
	if v.PtrPart != nil {
		dst = append(dst, ",\"ptr_only\":"...)
		dst = odjsonrt.AppendInt(dst, int64(v.PtrPart.PtrOnly))
	}
	dst = append(dst, ",\"Label\":\""...)
	dst, err = odjsonrt.AppendStringBodyChecked(dst, string(v.Label), m)
	if err != nil {
		return nil, err
	}
	dst = append(dst, "\",\"named\":{\"valu"...)
	dst = append(dst, "e\":"...)
	dst = odjsonrt.AppendInt(dst, int64(v.Named.Value))
	dst = append(dst, "},\"own\":\""...)
	dst, err = odjsonrt.AppendStringBodyChecked(dst, string(v.Own), m)
	if err != nil {
		return nil, err
	}
	dst[start] = '{'
	dst = append(dst, "\"}"...)
	return dst, nil
}

